import React, { useState, useEffect } from 'react';
import { Container, Row, Col, Card, Table, Button, Modal, Form, Badge } from 'react-bootstrap';
import { toast } from 'react-toastify';
import { logistikAPI } from '../../services/api';

const ManageRooms = () => {
  const [rooms, setRooms] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showModal, setShowModal] = useState(false);
  const [editMode, setEditMode] = useState(false);
  const [currentRoom, setCurrentRoom] = useState(null);
  const [formData, setFormData] = useState({
    name: '',
    capacity: '',
    location: '',
    description: '',
    is_active: true
  });

  useEffect(() => {
    fetchRooms();
  }, []);

  const fetchRooms = async () => {
    try {
      setLoading(true);
      const response = await logistikAPI.getRooms();
      setRooms(response.data);
    } catch (error) {
      console.error('Error fetching rooms:', error);
      toast.error('Gagal memuat data ruangan');
    } finally {
      setLoading(false);
    }
  };

  const handleOpenModal = (room = null) => {
    if (room) {
      setEditMode(true);
      setCurrentRoom(room);
      setFormData({
        name: room.name,
        capacity: room.capacity,
        location: room.location,
        description: room.description || '',
        is_active: room.is_active
      });
    } else {
      setEditMode(false);
      setCurrentRoom(null);
      setFormData({
        name: '',
        capacity: '',
        location: '',
        description: '',
        is_active: true
      });
    }
    setShowModal(true);
  };

  const handleCloseModal = () => {
    setShowModal(false);
    setEditMode(false);
    setCurrentRoom(null);
  };

  const handleChange = (e) => {
    const value = e.target.type === 'checkbox' ? e.target.checked : e.target.value;
    setFormData({
      ...formData,
      [e.target.name]: value
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    
    try {
      const submitData = {
        ...formData,
        capacity: parseInt(formData.capacity)
      };

      if (editMode) {
        await logistikAPI.updateRoom(currentRoom.id, submitData);
        toast.success('Ruangan berhasil diperbarui!');
      } else {
        await logistikAPI.createRoom(submitData);
        toast.success('Ruangan berhasil ditambahkan!');
      }
      
      fetchRooms();
      handleCloseModal();
    } catch (error) {
      console.error('Error saving room:', error);
      toast.error('Gagal menyimpan ruangan');
    }
  };

  const handleDelete = async (id) => {
    if (window.confirm('Apakah Anda yakin ingin menghapus ruangan ini?')) {
      try {
        await logistikAPI.deleteRoom(id);
        toast.success('Ruangan berhasil dihapus!');
        fetchRooms();
      } catch (error) {
        console.error('Error deleting room:', error);
        toast.error('Gagal menghapus ruangan');
      }
    }
  };

  if (loading) {
    return (
      <div className="text-center py-5">
        <div className="spinner-border" role="status">
          <span className="visually-hidden">Loading...</span>
        </div>
      </div>
    );
  }

  return (
    <Container fluid>
      {/* Header */}
      <Row className="mb-4">
        <Col>
          <h2>Kelola Ruangan</h2>
          <p className="text-muted">Manage ruangan meeting yang tersedia</p>
        </Col>
        <Col xs="auto">
          <Button variant="primary" onClick={() => handleOpenModal()}>
            <i className="fas fa-plus me-2"></i>
            Tambah Ruangan
          </Button>
        </Col>
      </Row>

      {/* Rooms Table */}
      <Row>
        <Col>
          <Card>
            <Card.Body>
              {rooms.length > 0 ? (
                <Table responsive hover>
                  <thead>
                    <tr>
                      <th>Nama Ruangan</th>
                      <th>Kapasitas</th>
                      <th>Lokasi</th>
                      <th>Deskripsi</th>
                      <th>Status</th>
                      <th>Aksi</th>
                    </tr>
                  </thead>
                  <tbody>
                    {rooms.map((room) => (
                      <tr key={room.id}>
                        <td>
                          <strong>{room.name}</strong>
                        </td>
                        <td>{room.capacity} orang</td>
                        <td>{room.location}</td>
                        <td>{room.description || '-'}</td>
                        <td>
                          <Badge bg={room.is_active ? 'success' : 'secondary'}>
                            {room.is_active ? 'Aktif' : 'Nonaktif'}
                          </Badge>
                        </td>
                        <td>
                          <div className="btn-group">
                            <Button
                              variant="outline-primary"
                              size="sm"
                              onClick={() => handleOpenModal(room)}
                            >
                              <i className="fas fa-edit"></i>
                            </Button>
                            <Button
                              variant="outline-danger"
                              size="sm"
                              onClick={() => handleDelete(room.id)}
                            >
                              <i className="fas fa-trash"></i>
                            </Button>
                          </div>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </Table>
              ) : (
                <div className="text-center py-5">
                  <i className="fas fa-building fa-3x text-muted mb-3"></i>
                  <h5>Belum ada ruangan</h5>
                  <p className="text-muted">Tambahkan ruangan untuk dapat digunakan dalam booking</p>
                  <Button variant="primary" onClick={() => handleOpenModal()}>
                    Tambah Ruangan
                  </Button>
                </div>
              )}
            </Card.Body>
          </Card>
        </Col>
      </Row>

      {/* Add/Edit Modal */}
      <Modal show={showModal} onHide={handleCloseModal} size="lg">
        <Modal.Header closeButton>
          <Modal.Title>
            {editMode ? 'Edit Ruangan' : 'Tambah Ruangan'}
          </Modal.Title>
        </Modal.Header>
        <Form onSubmit={handleSubmit}>
          <Modal.Body>
            <Row>
              <Col md={6}>
                <Form.Group className="mb-3">
                  <Form.Label>Nama Ruangan *</Form.Label>
                  <Form.Control
                    type="text"
                    name="name"
                    value={formData.name}
                    onChange={handleChange}
                    placeholder="Contoh: Meeting Room A"
                    required
                  />
                </Form.Group>
              </Col>
              <Col md={6}>
                <Form.Group className="mb-3">
                  <Form.Label>Kapasitas *</Form.Label>
                  <Form.Control
                    type="number"
                    name="capacity"
                    value={formData.capacity}
                    onChange={handleChange}
                    min="1"
                    max="100"
                    placeholder="10"
                    required
                  />
                </Form.Group>
              </Col>
            </Row>

            <Form.Group className="mb-3">
              <Form.Label>Lokasi *</Form.Label>
              <Form.Control
                type="text"
                name="location"
                value={formData.location}
                onChange={handleChange}
                placeholder="Contoh: Lantai 2, Wing A"
                required
              />
            </Form.Group>

            <Form.Group className="mb-3">
              <Form.Label>Deskripsi</Form.Label>
              <Form.Control
                as="textarea"
                rows={3}
                name="description"
                value={formData.description}
                onChange={handleChange}
                placeholder="Deskripsi fasilitas ruangan..."
              />
            </Form.Group>

            <Form.Group className="mb-3">
              <Form.Check
                type="checkbox"
                name="is_active"
                checked={formData.is_active}
                onChange={handleChange}
                label="Aktif (dapat digunakan untuk booking)"
              />
            </Form.Group>
          </Modal.Body>
          <Modal.Footer>
            <Button variant="secondary" onClick={handleCloseModal}>
              Batal
            </Button>
            <Button variant="primary" type="submit">
              {editMode ? 'Update' : 'Simpan'}
            </Button>
          </Modal.Footer>
        </Form>
      </Modal>
    </Container>
  );
};

export default ManageRooms;
